window.HOEREN_TESTS[4] = {"id":"wohnen-und-umzug","name":"Wohnen und Umzug","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Mieter, am Donnerstag wird die Heizungsanlage repariert. Von 9 bis 14 Uhr haben wir leider keine Heizung im ganzen Haus. Das warme Wasser läuft aber normal weiter, damit ist alles in Ordnung. Wir entschuldigen uns für die Unannehmlichkeiten. Wenn es kalt wird, lassen Sie die Fenster bitte zu. Mit freundlichen Grüßen, Ihre Hausverwaltung.","gender":"f","q":"Was funktioniert am Donnerstag nicht?","opts":["Das warme Wasser.","Die Heizung.","Alles im Haus."],"correct":1},{"transcript":"Hallo Herr Schmidt, hier ist die Möbelfirma Wohnglück. Ihre bestellte Couch wird am Freitag zwischen 9 und 12 Uhr geliefert. Bitte seien Sie zu Hause oder geben Sie uns eine andere Adresse durch. Wenn niemand öffnet, müssen wir mit dem Möbel zurückfahren und Sie zahlen 60 Euro Aufpreis für eine zweite Lieferung. Rückruf nicht nötig.","gender":"m","q":"Was passiert, wenn niemand zu Hause ist?","opts":["Es gibt 60 Euro Aufpreis für eine zweite Lieferung.","Die Lieferung ist umsonst.","Sie bekommen einen neuen Termin gratis."],"correct":0},{"transcript":"Suchen Sie eine schöne Wohnung in Bestlage? Wir haben gerade eine 3-Zimmer-Wohnung im Stadtzentrum, 75 Quadratmeter, mit Balkon. Die Miete ist 1.200 Euro warm, das ist sehr fair für die Lage. Besichtigung am Samstag um 14 Uhr. Bitte vorher anrufen, weil wir nur 10 Interessenten reinlassen. Rufen Sie heute noch an! Tel. 089 / 123 456.","gender":"f","q":"Was kostet die Wohnung warm?","opts":["750 Euro.","1.200 Euro.","10 Euro pro Quadratmeter."],"correct":1},{"transcript":"Hi Lukas, hier ist deine Nachbarin Petra. Hey, ich habe ein Problem: Wasser läuft aus deiner Wohnung durch die Decke zu mir runter. Ich habe schon einen Eimer geholt, aber es wird schlimmer. Kannst du sofort nach Hause kommen oder einen Klempner schicken? Mein Telefon ist 0151 — du weißt ja. Bitte ganz schnell, danke!","gender":"f","q":"Was ist das Problem?","opts":["Lukas hat den Hauseingangsschlüssel verloren.","Petras Heizung funktioniert nicht mehr.","Wasser fließt aus Lukas' Wohnung in Petras Wohnung."],"correct":2},{"transcript":"Eine Information für alle Hausbewohner: Am Sonntag findet im Hof eine kleine Sommerparty statt. Alle sind herzlich eingeladen. Beginn ist um 15 Uhr, jeder bringt etwas zum Essen oder zum Trinken mit. Die Hausverwaltung stellt Tische und Stühle. Bei Regen verschieben wir auf den nächsten Sonntag. Bitte sagen Sie uns Bescheid, ob Sie kommen.","gender":"m","q":"Was sollen Hausbewohner mitbringen?","opts":["Tische und Stühle.","Geld für eine gemeinsame Bestellung.","Etwas zum Essen oder Trinken."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer übernimmt welche Aufgabe? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Anna","gender":"f","text":"Hallo Markus! Am Samstag ziehen wir um. Die Kisten stehen schon überall im Flur."},{"speaker":"Markus","gender":"m","text":"Ich habe den Plan auf dem Tisch. Wir verteilen die Aufgaben jetzt in Ruhe."},{"speaker":"Anna","gender":"f","text":"Ich hole den Lkw um acht beim Verleih. Der Schlüssel liegt dort früh bereit."},{"speaker":"Markus","gender":"m","text":"Dann fahre ich nicht selbst hin. Ich packe die Küche mit Tellern und Töpfen ein."},{"speaker":"Anna","gender":"f","text":"In der Küche steht viel Glas. Kaufen wir für das Wohnzimmer neue Möbel?"},{"speaker":"Markus","gender":"m","text":"Nein. Neue Möbel kaufen wir nicht. Die alten Schränke passen noch in die Zimmer."},{"speaker":"Anna","gender":"f","text":"Pass bitte gut auf die empfindlichen Sachen. Die Teller sind alt und dünn."},{"speaker":"Markus","gender":"m","text":"Mache ich ganz vorsichtig. Lisa packt die Bücher in kleine stabile Kisten."},{"speaker":"Anna","gender":"f","text":"Die Bücher kommen in Karton drei. Danach müssen wir die alten Zimmer sauber hinterlassen."},{"speaker":"Markus","gender":"m","text":"Tim putzt die alte Wohnung am Sonntag. Er bringt eigenes Putzzeug mit."},{"speaker":"Anna","gender":"f","text":"Die alte Wohnung glänzt dann wieder. Sollen wir Pizza für alle Helfer bestellen?"},{"speaker":"Markus","gender":"m","text":"Pizza gibt es am Samstag nicht. Meine Mutter kocht eine große Suppe für uns."},{"speaker":"Anna","gender":"f","text":"Im neuen Haus bleibt das Netz noch tot. Ohne Netz können wir nicht arbeiten."},{"speaker":"Markus","gender":"m","text":"Toms Vater richtet das Internet ein. Er kommt nachmittags mit dem Gerät."},{"speaker":"Anna","gender":"f","text":"Einverstanden. Ich hänge den Plan an die Haustür. Bis Samstag ganz früh."}],"options":[{"letter":"a","text":"meldet den Strom an"},{"letter":"b","text":"richtet das Internet ein"},{"letter":"c","text":"dekoriert die neue Wohnung"},{"letter":"d","text":"packt die Küche"},{"letter":"e","text":"packt die Bücher"},{"letter":"f","text":"kauft neue Möbel"},{"letter":"g","text":"holt den Lkw"},{"letter":"h","text":"putzt die alte Wohnung"},{"letter":"i","text":"bringt Pizza für alle"}],"items":[{"person":"Anna","correct":"g"},{"person":"Markus","correct":"d"},{"person":"Lisa","correct":"e"},{"person":"Tim","correct":"h"},{"person":"Toms Vater","correct":"b"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Vermieter","gender":"m","text":"Sie interessieren sich für die Wohnung?"},{"speaker":"Interessentin","gender":"f","text":"Ja, sehr, wie hoch ist die Miete?"},{"speaker":"Vermieter","gender":"m","text":"850 Euro kalt. Plus Nebenkosten 150 Euro — also 1.000 Euro warm. Die Heizkosten sind schon dabei."},{"speaker":"Interessentin","gender":"f","text":"Gut, wie hoch ist die Kaution?"},{"speaker":"Vermieter","gender":"m","text":"Drei Monatsmieten, also 2.550 Euro. Fragen Sie, wenn etwas unklar ist. Wir freuen uns auf Sie!"}],"q":"Wie hoch sind die monatlichen Nebenkosten?","opts":["150 Euro.","850 Euro.","1.000 Euro."],"correct":0},{"lines":[{"speaker":"Nachbarin","gender":"f","text":"Entschuldigung, ich muss mich beschweren. Ihre Musik ist zu laut, vor allem nachts nach 22 Uhr."},{"speaker":"Mieter","gender":"m","text":"Oh, das tut mir leid! Am Morgen ist es doch ruhig, oder?"},{"speaker":"Nachbarin","gender":"f","text":"Am Morgen ja. Aber jeden Abend ist es laut, nicht nur am Wochenende. Bitte nach 22 Uhr leiser!"},{"speaker":"Mieter","gender":"m","text":"Klar, ab heute nach 22 Uhr leise. Versprochen!"},{"speaker":"Nachbarin","gender":"f","text":"Danke, das reicht mir. Schönen Abend!"}],"q":"Wann ist die Musik besonders störend?","opts":["Am Morgen.","Nach 22 Uhr abends.","Nur am Wochenende."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Ich brauche ein neues Bett. Was haben Sie?"},{"speaker":"Verkäuferin","gender":"f","text":"Welche Größe? Einzelbett 90, Doppelbett 140 oder King-size 180 breit?"},{"speaker":"Kunde","gender":"m","text":"Doppelbett, also 140."},{"speaker":"Verkäuferin","gender":"f","text":"Wir haben eines aus Holz für 450 Euro. Oder ein modernes weißes für 650 Euro, sehr schön."},{"speaker":"Kunde","gender":"m","text":"Ich nehme das aus Holz. Holz hält länger als Lack, finde ich."}],"q":"Welches Bett kauft der Kunde?","opts":["Das moderne weiße Bett für 650 Euro.","Ein King-size-Bett.","Das Holzbett für 450 Euro."],"correct":2},{"lines":[{"speaker":"Mitarbeiterin","gender":"f","text":"Stadtwerke München, guten Tag."},{"speaker":"Kunde","gender":"m","text":"Hallo, ich bin gerade umgezogen und möchte den Strom anmelden."},{"speaker":"Mitarbeiterin","gender":"f","text":"Ihre alte Adresse und die neue, bitte."},{"speaker":"Kunde","gender":"m","text":"Alte Adresse: Goethestraße 5. Neue Adresse: Bahnhofstraße 27, Wohnung 3B."},{"speaker":"Mitarbeiterin","gender":"f","text":"Notiert, Sie bekommen einen Vertrag in zwei Tagen per Post. Bitte unterschreiben und uns zurückschicken. Bis bald! Online registrieren müssen Sie sich nicht extra."}],"q":"Was muss der Kunde nach dem Anruf machen?","opts":["Sich online registrieren.","Den Vertrag unterschreiben und zurückschicken.","Ins Büro der Stadtwerke kommen."],"correct":1},{"lines":[{"speaker":"Kunde","gender":"m","text":"Ich brauche ein neues Bett. Was haben Sie?"},{"speaker":"Verkäuferin","gender":"f","text":"Welche Größe? Einzelbett 90, Doppelbett 140 oder King-size 180? Für zwei Personen?"},{"speaker":"Kunde","gender":"m","text":"Doppelbett, also 140."},{"speaker":"Verkäuferin","gender":"f","text":"Wir haben eines aus Holz für 450 Euro. Oder ein modernes weißes für 650 Euro."},{"speaker":"Kunde","gender":"m","text":"Ich nehme das aus Holz. Holz hält länger als Lack. Nehmen Sie es gleich mit?"}],"q":"Welches Bett kauft der Kunde?","opts":["Ein Doppelbett aus Holz.","Ein Einzelbett.","Ein weißes King-size-Bett."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Vogel, einer Immobilienmaklerin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Vogel, Sie sind Immobilienmaklerin seit 15 Jahren. Wie hat sich der Markt in dieser Zeit verändert?"},{"speaker":"Vogel","gender":"f","text":"Sehr stark, vor 15 Jahren konnte man eine Wohnung schnell finden. Heute warten Kunden manchmal Monate auf eine passende Wohnung — vor allem in den großen Städten. Die Preise haben sich in dieser Zeit fast verdoppelt."},{"speaker":"Reporter","gender":"m","text":"Welche Wohnungen werden am meisten gefragt?"},{"speaker":"Vogel","gender":"f","text":"Kleine Wohnungen mit ein oder zwei Zimmern im Zentrum sind die meist gefragten. Familien suchen größere Wohnungen, aber die gibt es kaum noch. Häuser sind seltener gefragt, weil die meisten Menschen keinen Garten pflegen wollen."},{"speaker":"Reporter","gender":"m","text":"Mit was für Kunden arbeiten Sie?"},{"speaker":"Vogel","gender":"f","text":"Sehr unterschiedlich, junge Paare, die zum ersten Mal kaufen. Familien, die größer werden möchten. Ältere Menschen, die kleiner werden wollen, weil ihre Kinder ausgezogen sind. Auch Investoren — aber das mache ich nicht so gern, ehrlich gesagt."},{"speaker":"Reporter","gender":"m","text":"Wie sind Ihre Arbeitszeiten?"},{"speaker":"Vogel","gender":"f","text":"Sehr unregelmäßig. Ich bin viel am Wochenende und am Abend unterwegs, weil die Kunden nur dann Zeit haben. Mittwochs habe ich frei — das ist mein Familientag mit Mann und Kindern."},{"speaker":"Reporter","gender":"m","text":"Haben Sie selbst eine Traum-Wohnung?"},{"speaker":"Vogel","gender":"f","text":"Ja, ein altes Haus auf dem Land mit großem Garten. Genau das Gegenteil von dem, was meine Kunden meistens suchen. Aber das ist meine private Hoffnung für später — vielleicht in 10 Jahren."}],"items":[{"q":"Familien suchen meistens kleine Wohnungen.","correct":"nein"},{"q":"Wohnungspreise sind heute viel höher als vor 15 Jahren.","correct":"ja"},{"q":"Mittwochs ist Frau Vogel mit ihrer Familie zusammen.","correct":"ja"},{"q":"Sie arbeitet besonders gern mit Investoren.","correct":"nein"},{"q":"Ihr Traum ist ein Haus auf dem Land.","correct":"ja"}]}]};
